from fastapi import FastAPI, WebSocket, UploadFile, File
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse, StreamingResponse
import asyncio
import json
import uuid
import os
from generators.image_gen import generate_image_task
from generators.audio_gen import generate_audio_task
from utils.ffmpeg_proc import compress_for_mobile

app = FastAPI(title="CineForge Backend")

# Permitir conexiones desde el móvil (ajusta IP según tu red local)
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"], 
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# Almacén temporal de estado de tareas
task_status = {}

@app.post("/generate/image")
async def create_image(prompt: str, style: str = "cinematic"):
    task_id = str(uuid.uuid4())
    task_status[task_id] = {"status": "processing", "progress": 0}

    # Ejecutar en background para no bloquear la API
    asyncio.create_task(run_image_generation(task_id, prompt, style))

    return {"task_id": task_id, "status": "queued"}

async def run_image_generation(task_id: str, prompt: str, style: str):
    try:
        # 1. Llamar al motor de IA (ej. ComfyUI o Diffusers directo)
        image_path = await generate_image_task(prompt, style)

        # 2. Post-procesamiento para móvil (compresión inteligente)
        mobile_optimized_path = compress_for_mobile(image_path, target_size="1MB")

        task_status[task_id] = {
            "status": "completed", 
            "url": f"/media/{os.path.basename(mobile_optimized_path)}",
            "progress": 100
        }
    except Exception as e:
        task_status[task_id] = {"status": "failed", "error": str(e)}

@app.get("/status/{task_id}")
async def get_status(task_id: str):
    return task_status.get(task_id, {"status": "not_found"})

@app.websocket("/ws/{task_id}")
async def websocket_endpoint(websocket: WebSocket, task_id: str):
    await websocket.accept()
    try:
        while True:
            status = task_status.get(task_id, {})
            await websocket.send_json(status)
            if status.get("status") in ["completed", "failed"]:
                break
            await asyncio.sleep(1)
    except:
        pass

# Servir archivos generados
from fastapi.staticfiles import StaticFiles
app.mount("/media", StaticFiles(directory="./output/mobile_ready"), name="media")
```

