import subprocess
import os

def compress_for_mobile(input_path: str, target_size: str = "1MB") -> str:
    output_path = input_path.replace(".png", ".webp").replace("./output/raw/", "./output/mobile_ready/")

    # Convertir a WebP para web/móvil (mucho más ligero que PNG/JPG)
    cmd = [
        "ffmpeg", "-i", input_path, 
        "-q:v", "80", # Calidad
        "-vf", "scale=1080:-1", # Redimensionar para móvil
        output_path
    ]
    subprocess.run(cmd, check=True)
    return output_path
