### `server/main.py` - FastAPI + WebSocket + Streaming
```python
from fastapi import FastAPI, WebSocket, WebSocketDisconnect
from fastapi.responses import StreamingResponse
import asyncio
import json
import subprocess
from core.comfy_bridge import ComfyBridge
from core.audio_engine import AudioEngine
from core.stream_manager import StreamManager

app = FastAPI(title="CineForge Cloud-Local Server")
comfy = ComfyBridge()
audio = AudioEngine()
stream_mgr = StreamManager()

# --- WEBSOCKET PARA CONTROL EN TIEMPO REAL ---
@app.websocket("/ws/control")
async def control_endpoint(websocket: WebSocket):
    await websocket.accept()
    try:
        while True:
            data = await websocket.receive_text()
            cmd = json.loads(data)

            if cmd["type"] == "generate_image":
                # Envía a ComfyUI y notifica progreso
                task_id = comfy.queue_prompt(cmd["workflow"])
                await websocket.send_json({
                    "type": "task_started", 
                    "task_id": task_id,
                    "estimated_time": 45
                })

            elif cmd["type"] == "generate_audio":
                path = audio.generate_music(
                    cmd["prompt"], 
                    cmd.get("duration", 15)
                )
                await websocket.send_json({
                    "type": "audio_ready", 
                    "path": path,
                    "url": f"/audio/{path.split('/')[-1]}"
                })

            elif cmd["type"] == "get_status":
                status = comfy.get_queue_status()
                await websocket.send_json({"type": "status", "data": status})

    except WebSocketDisconnect:
        print("Cliente desconectado")

# --- STREAMING DE VIDEO EN VIVO (Preview) ---
@app.get("/stream/preview")
async def video_stream():
    """Stream H.264 low-latency para preview en móvil"""
    async def generate():
        # FFmpeg captura salida de ComfyUI o genera test pattern
        process = await stream_mgr.get_preview_stream()
        while True:
            chunk = await process.stdout.read(8192)
            if not chunk:
                break
            yield chunk
    return StreamingResponse(generate(), media_type="video/mp4")

# --- SERVICIO DE ARCHIVOS GENERADOS ---
@app.get("/output/{filename}")
async def serve_output(filename: str):
    from fastapi.responses import FileResponse
    return FileResponse(f"./output/{filename}")

# --- HEALTH CHECK PARA MÓVIL ---
@app.get("/health")
async def health():
    gpu_info = comfy.get_gpu_status()
    return {
        "status": "online",
        "gpu_vram_free": gpu_info["vram_free_gb"],
        "queue_size": comfy.get_queue_size(),
        "mobile_optimized": True
    }
